def prepare(d):
 records=[]
 for c in d['catalog']['entries']:
  k=c['card_id'];ts=c['topic_ids'];jobs=JOB_OVERRIDES.get(k,[j for j,topics in JOB_TOPICS.items() if set(ts)&set(topics.split())])
  roles=[r for r,ids in ROLE_GROUPS.items() if k in ids.split()]
  methods=[r for r,ids in METHOD_GROUPS.items() if k in ids.split()]
  foundations=[f for f,title,topics in FOUNDATIONS if set(ts)&set(topics.split())]
  if k=='FC014':foundations.append('F2')
  records.append({key:c[key] for key in ['card_id','company','company_key','item','booths','target','technology','human_boundary','depth','exhibition_status','product_stage','evidence_ids','source_urls','exhibitor_urls_2026','exhibitor_urls_2024','related_note']}|dict(jobs=jobs,roles=roles,methods=methods,foundations=foundations,tag=TAGS.get(k,''),classification_type='調査者による分類・分析',classification_basis='保存済み公式説明と既存カードの担当タスク・方式を読んで配置。工程は技術テーマとの対応。役割・方式が特定できない場合は確認待ち。製品名のAI表記だけで方式を決めない。'))
 assert len(records)==len({r['card_id'] for r in records})==344
 ids={r['card_id'] for r in records}
 assert all(k in ids for group in [ROLE_GROUPS,METHOD_GROUPS] for value in group.values() for k in value.split())
 result=dict(date='2026-10-19',jobs=JOBS,roles=ROLES,methods=METHODS,foundations=FOUNDATIONS,records=records,scope=dict(total=len(records),roles_classified=sum(bool(r['roles'])for r in records),methods_classified=sum(bool(r['methods'])for r in records),job_unconfirmed=sum(not r['jobs']for r in records),note='重複配置あり。方式・役割の分類は分析。未配置は未確認であり、機能なし・企業なしという意味ではない。'))
 p=pathlib.Path(__file__).resolve().parents[1]/'data/research/report_v0/matrix_classification.json'
 p.write_text(json.dumps(result,ensure_ascii=False,indent=2),'utf-8')
 return result

