def build(data,h):
 def table(mode,rows):
  s=f'<div data-matrix-mode="{mode}"'+(' hidden' if mode=='B' else '')+'><div class="scroll"><table class="matrix-table"><thead><tr><th>仕事 →<br>'+('担当する役割 ↓' if mode=='A' else '使う技術方式 ↓')+'</th>'+''.join(f'<th>{h(name)}</th>'for k,name in JOBS)+'</tr></thead><tbody>'
  for key,title,desc in rows:
   s+=f'<tr><th>{h(title)}<span>{h(desc)}</span></th>'+''.join(f'<td><button class="matrix-open" type="button" data-cell-mode="{mode}" data-cell-row="{key}" data-cell-job="{j}" aria-label="{h(title+"："+name)}"></button></td>'for j,name in JOBS)+'</tr>'
  return s+'</tbody></table></div></div>'
 return '<div class="matrix-switch" role="group" aria-label="マップの表示方式"><button type="button" data-map-mode-choice="A" aria-pressed="true">A　仕事 × 役割</button><button type="button" data-map-mode-choice="B" aria-pressed="false">B　仕事 × 技術方式</button><button type="button" data-map-mode-choice="cards" aria-pressed="false">従来のカード型</button></div><div data-matrix-tools><p class="matrix-intro">各セルは最大2例を表示。クリックすると該当する全候補と公式リンクを右側に表示します。1社・1製品の複数配置があります。役割・方式は調査者の分類〈分析〉で、自律性・成熟度の順位ではありません。</p><div class="toolbar matrix-toolbar"><input id="matrix-search" aria-label="マップ内を検索" placeholder="企業・技術・ブースを検索"><select id="matrix-depth" aria-label="調査の深さ"><option value="ALL">すべての候補</option><option value="reviewed">詳細比較・個別タスク整理</option></select></div><p class="meta small" id="matrix-count"></p></div>'+table('A',ROLES)+table('B',METHODS)+'<div data-matrix-tools><div class="matrix-pools"><button type="button" data-matrix-pool="unconfirmed" id="matrix-pending"></button><button type="button" data-matrix-pool="job-unknown" id="matrix-job-unknown"></button></div><div class="matrix-foundations">'+''.join(f'<button type="button" data-matrix-pool="{key}"><b>{h(title)}</b><br><span data-foundation-count="{key}"></span></button>'for key,title,topics in FOUNDATIONS)+'</div><p class="matrix-legend">横断基盤は上段の工程と重複する場合があります。AIという呼称だけで方式を確定せず、未確認の候補は確認待ち一覧に残しています。空欄は今回の配置なし。需要・競合・技術の空白を示すものではありません。</p></div><dialog class="matrix-dialog" id="matrix-dialog" aria-labelledby="matrix-dialog-title"><div class="matrix-dialog-head"><button class="matrix-dialog-close" id="matrix-close" type="button" aria-label="閉じる">閉じる</button><h2 id="matrix-dialog-title"></h2><p class="meta small" id="matrix-dialog-count"></p></div><div class="matrix-dialog-body" id="matrix-dialog-body"></div></dialog>'

JS='''
let matrixMode='A';
const matrixRecords=matrixData.records, matrixJobs=new Map(matrixData.jobs),matrixRows={A:new Map(matrixData.roles.map(r=>[r[0],r[1]])),B:new Map(matrixData.methods.map(r=>[r[0],r[1]]))};
function matrixFiltered(){const q=document.getElementById('matrix-search').value.toLocaleLowerCase(),reviewed=document.getElementById('matrix-depth').value==='reviewed';return matrixRecords.filter(c=>(!reviewed||c.depth!=='出展説明の一次分類')&&[c.company,c.item,c.target,c.technology,c.card_id,...c.booths].join(' ').toLocaleLowerCase().includes(q))}
function matrixCell(c,mode,row,job){return c.jobs.includes(job)&&c[mode==='A'?'roles':'methods'].includes(row)}
function mxEl(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function refreshMatrices(){const rows=matrixFiltered();document.getElementById('matrix-count').textContent=new Set(rows.map(c=>c.company_key)).size+'社・'+rows.length+'カードを対象（セル間・横断基盤との重複あり）';document.querySelectorAll('[data-cell-mode]').forEach(b=>{const found=rows.filter(c=>matrixCell(c,b.dataset.cellMode,b.dataset.cellRow,b.dataset.cellJob));b.replaceChildren();if(!found.length){b.append(mxEl('span','今回の配置なし','matrix-empty'));b.disabled=true;return}b.disabled=false;b.append(mxEl('span',new Set(found.map(c=>c.company_key)).size+'社・'+found.length+'カード','matrix-cell-count'));found.slice(0,2).forEach(c=>{const chip=mxEl('span',undefined,'matrix-chip');chip.append(mxEl('span',c.company,'chip-company'),mxEl('strong',c.target));chip.title=c.company+'／'+c.item+'／'+c.technology;if(c.tag)chip.append(mxEl('small',c.tag));b.append(chip)});b.append(mxEl('span',found.length>2?'ほか'+(found.length-2)+'件を含む全件を見る →':'詳細・公式出展ページを見る →','matrix-rest'))});const field=matrixMode==='B'?'methods':'roles';document.getElementById('matrix-pending').textContent=(matrixMode==='B'?'技術方式':'担当する役割')+'の確認待ち '+rows.filter(c=>!c[field].length).length+'件';document.getElementById('matrix-job-unknown').textContent='対象の仕事の確認待ち '+rows.filter(c=>!c.jobs.length).length+'件';document.querySelectorAll('[data-foundation-count]').forEach(e=>e.textContent=rows.filter(c=>c.foundations.includes(e.dataset.foundationCount)).length+'カード・全件を見る →')}
function setMapView(id,domain){const mode=['A','B','cards'].includes(id)?id:(/^D/.test(id||'')?'cards':'A');matrixMode=mode;document.querySelectorAll('[data-matrix-mode]').forEach(e=>e.hidden=e.dataset.matrixMode!==mode);document.querySelectorAll('[data-matrix-tools]').forEach(e=>e.hidden=mode==='cards');document.querySelectorAll('[data-map-mode-choice]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.mapModeChoice===mode)));const filter=/^D/.test(id||'')?id:(domain||'ALL');document.querySelectorAll('[data-map-domain]').forEach(e=>e.hidden=filter!=='ALL'&&e.dataset.mapDomain!==filter);document.querySelectorAll('[data-map-choice]').forEach(e=>e.classList.toggle('selected',e.dataset.mapChoice===filter));if(mode!=='cards')refreshMatrices()}
function matrixLink(url,label){const a=mxEl('a',label+' ↗');a.href=url;a.target='_blank';a.rel='noopener';return a}
function openMatrix(title,rows){const box=document.getElementById('matrix-dialog-body');box.replaceChildren();document.getElementById('matrix-dialog-title').textContent=title;document.getElementById('matrix-dialog-count').textContent=new Set(rows.map(c=>c.company_key)).size+'社・'+rows.length+'カード。配置は分析、技術説明は保存済み公式説明の要約・抜粋。';rows.forEach(c=>{const a=mxEl('article',undefined,'matrix-result');a.append(mxEl('h3',c.company),mxEl('p',c.item+'　ブース '+c.booths.join(' / '),'meta'),mxEl('p',c.target,'matrix-target'),mxEl('p',c.technology));if(c.tag)a.append(mxEl('p',c.tag,'catalog-note'));if(c.related_note)a.append(mxEl('p',c.related_note,'meta'));const links=mxEl('div',undefined,'catalog-links');c.exhibitor_urls_2026.forEach(u=>links.append(matrixLink(u,'JIMTOF2026 出展ページ')));c.exhibitor_urls_2024.forEach(u=>links.append(matrixLink(u,'JIMTOF2024 出展ページ')));a.append(links);const year=mxEl('a','企業・技術の年度比較を見る →');year.href='#years/'+c.card_id;year.onclick=()=>document.getElementById('matrix-dialog').close();a.append(year);const more=mxEl('details');more.append(mxEl('summary','人の役割・展示段階・分類根拠'));more.append(mxEl('p',c.human_boundary),mxEl('p',c.exhibition_status+' ／ '+c.product_stage),mxEl('p',c.classification_basis),mxEl('p','根拠ID：'+c.evidence_ids.join(' / '),'meta'));c.source_urls.filter(u=>!c.exhibitor_urls_2026.includes(u)&&!c.exhibitor_urls_2024.includes(u)).forEach(u=>more.append(matrixLink(u,'公式技術資料')));a.append(more);box.append(a)});if(!rows.length)box.append(mxEl('p','現在の絞り込み条件に該当する候補はありません。'));document.getElementById('matrix-dialog').showModal();document.getElementById('matrix-dialog').scrollTop=0}
document.querySelectorAll('[data-map-mode-choice]').forEach(e=>e.onclick=()=>location.hash='map/'+e.dataset.mapModeChoice);
document.getElementById('matrix-search').oninput=refreshMatrices;document.getElementById('matrix-depth').onchange=refreshMatrices;document.getElementById('matrix-close').onclick=()=>document.getElementById('matrix-dialog').close();
document.querySelectorAll('[data-cell-mode]').forEach(b=>b.onclick=()=>openMatrix(matrixJobs.get(b.dataset.cellJob)+' × '+matrixRows[b.dataset.cellMode].get(b.dataset.cellRow),matrixFiltered().filter(c=>matrixCell(c,b.dataset.cellMode,b.dataset.cellRow,b.dataset.cellJob))));
document.querySelectorAll('[data-matrix-pool]').forEach(b=>b.onclick=()=>{const pool=b.dataset.matrixPool,field=matrixMode==='B'?'methods':'roles';let rows=matrixFiltered(),title;if(pool==='unconfirmed'){rows=rows.filter(c=>!c[field].length);title=(matrixMode==='B'?'技術方式':'担当する役割')+'の確認待ち'}else if(pool==='job-unknown'){rows=rows.filter(c=>!c.jobs.length);title='対象の仕事の確認待ち'}else{rows=rows.filter(c=>c.foundations.includes(pool));title=matrixData.foundations.find(x=>x[0]===pool)[1]}openMatrix(title,rows)});
'''

def script(data):
 return 'const matrixData='+json.dumps(data,ensure_ascii=False).replace('<','\\u003c')+';\n'+JS
